دالة فيبوناتشي(ن) {
    إذا (ن == ٠) { ارجع ٠ }
    وإلا إذا (ن == ١) { ارجع ١ }
    وإلا {
        متغير أ = ٠
        متغير ب = ١
        من_أجل (ع من ٢ إلى ن) {
            متغير ج = أ + ب
            أ = ب
            ب = ج
        }
        ارجع ب
    }
}
```

